export function encodeCsvField(value) {
  if (typeof value !== 'string') {
    throw new TypeError('value must be a string');
  }
  if (
    value === '' ||
    value.includes(',') ||
    value.includes('"') ||
    value.includes('\r') ||
    value.includes('\n')
  ) {
    return `"${value.replaceAll('"', '""')}"`;
  }
  return value;
}

