import { encodeCsvField } from './csv-field.mjs';

function recordDelimiterLength(text, index) {
  if (text[index] === '\r') {
    return text[index + 1] === '\n' ? 2 : 1;
  }
  if (text[index] === '\n') {
    return 1;
  }
  return 0;
}

export function parseCsv(text) {
  if (typeof text !== 'string') {
    throw new TypeError('text must be a string');
  }
  if (text === '') {
    return [];
  }

  const rows = [];
  let row = [];
  let field = '';
  let i = 0;
  let inQuotes = false;
  let afterQuotedField = false;

  const pushField = () => {
    row.push(field);
    field = '';
    afterQuotedField = false;
  };

  const pushRow = () => {
    rows.push(row);
    row = [];
  };

  while (i < text.length) {
    if (afterQuotedField) {
      if (text[i] === ',') {
        pushField();
        i += 1;
        continue;
      }
      const delim = recordDelimiterLength(text, i);
      if (delim > 0) {
        pushField();
        pushRow();
        i += delim;
        continue;
      }
      throw new SyntaxError('invalid character after closing quote');
    }

    if (inQuotes) {
      if (text[i] === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i += 2;
          continue;
        }
        inQuotes = false;
        afterQuotedField = true;
        i += 1;
        continue;
      }
      field += text[i];
      i += 1;
      continue;
    }

    if (text[i] === '"') {
      if (field.length > 0) {
        throw new SyntaxError('quote in unquoted field');
      }
      inQuotes = true;
      i += 1;
      continue;
    }

    if (text[i] === ',') {
      pushField();
      i += 1;
      continue;
    }

    const delim = recordDelimiterLength(text, i);
    if (delim > 0) {
      pushField();
      pushRow();
      i += delim;
      continue;
    }

    field += text[i];
    i += 1;
  }

  if (inQuotes) {
    throw new SyntaxError('unclosed quote');
  }
  if (afterQuotedField) {
    pushField();
    pushRow();
  } else if (field.length > 0 || row.length > 0) {
    row.push(field);
    pushRow();
  }

  return rows;
}

export function serializeCsv(rows) {
  if (!Array.isArray(rows)) {
    throw new TypeError('rows must be an array');
  }
  if (rows.length === 0) {
    return '';
  }
  for (const row of rows) {
    if (!Array.isArray(row) || row.length === 0) {
      throw new TypeError('each row must be a nonempty array');
    }
    for (const cell of row) {
      if (typeof cell !== 'string') {
        throw new TypeError('each field must be a string');
      }
    }
  }
  return rows.map((row) => row.map(encodeCsvField).join(',')).join('\r\n');
}

