import test from 'node:test';
import assert from 'node:assert/strict';
import { parseCsv, serializeCsv } from '../src/csv.mjs';
test('simple one-record values',()=>{assert.deepEqual(parseCsv('a,b'),[['a','b']]);assert.equal(serializeCsv([['a','b']]),'a,b');});
test('quoted comma and doubled quote fields',()=>{assert.deepEqual(parseCsv('"a,b","say ""hi"""'),[['a,b','say "hi"']]);});
